<a class="Title2" id="initialisation-de-la-barre-d-outils-de-la-fenetre-principale_gestion-des-fenetres-popup" href="#initialisation-de-la-barre-d-outils-de-la-fenetre-principale">Gestion des fenêtres popup</a>
</h2><br><span class="GText2" style="
color: #00ff00;
">// cPopupMenuHolder.h</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">#pragma once

#include &lt;QObject&gt;
#include &lt;QAction&gt;
#include &lt;vector&gt;

class QToolButton;

class cPopupMenuHolder : public QObject
{
    Q_OBJECT

public:
    explicit cPopupMenuHolder(QObject *parent = nullptr);
    ~cPopupMenuHolder();
    QToolButton *create();
    void setChecked(size_t idx, bool checked);
    QIcon getIcon(size_t idx);

    template &lt;class SlotType&gt;
    QAction *addAction(QIcon const &amp;icon, QString const &amp;text,
                       SlotType slot, bool checkable)
    {
        QAction *action = addActionImpl(icon, text, checkable);
        connect(action, &amp;QAction::triggered, std::move(slot));
        return action;
    }

    QAction *addAction(QIcon const &amp;icon, QString const &amp;text,
                       QObject const *receiver, char const *member, bool checkable)
    {
        QAction *p = addActionImpl(icon, text, checkable);
        connect(p, SIGNAL(triggered()), receiver, member);
        return p;
    }

private:
    QAction *addActionImpl(QIcon const &amp;icon, QString const &amp;text, bool checkable);

private:
    std::vector&lt;QAction *&gt; m_actions;
};</pre><br><span class="GText2" style="
color: #00ff00;
">// cPopupMenuHolder.cpp</span><br><pre class="GCode1 Code1 AceCode" data-mode="c_cpp" data-theme="gruvbox" data-bg-color="transparent" style="background-color: transparent;">#include "cPopupMenuHolder.h"
#include &lt;QMenu&gt;
#include &lt;QToolButton&gt;

struct Hotkey
{
    Hotkey() = default;
    Hotkey(QKeySequence const &amp;key, char const *slot) : m_key(key), m_slot(slot) {}

    QKeySequence m_key = 0;
    char const *m_slot = nullptr;
};

cPopupMenuHolder::cPopupMenuHolder(QObject *parent)
    : QObject(parent)
{
}

cPopupMenuHolder::~cPopupMenuHolder()
{
}

QAction *cPopupMenuHolder::addActionImpl(QIcon const &amp;icon, QString const &amp;text, bool checkable)
{
    QAction *action = new QAction(icon, text, this);
    action-&gt;setCheckable(checkable);
    m_actions.push_back(action);
    return action;
}

QToolButton *cPopupMenuHolder::create()
{
    QMenu *menu = new QMenu();
    for (auto *action : m_actions)
    {
        menu-&gt;addAction(action);
    }

    QToolButton *toolButton = new QToolButton;
    toolButton-&gt;setPopupMode(QToolButton::MenuButtonPopup);
    toolButton-&gt;setMenu(menu);
    return toolButton;
}

void cPopupMenuHolder::setChecked(size_t idx, bool checked)
{
    m_actions[idx]-&gt;setChecked(checked);
}

QIcon cPopupMenuHolder::getIcon(size_t idx)
{
    return m_actions[idx]-&gt;icon();
}</pre><br><h2 class="GTitle1 Title1">
